SELECT 'gongkao', '社会现象类', 'kp-ms-ana-phenomenon', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：社会现象类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "对于当前发生的热点事件、社会风气，谈谈你的看法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、答题框架（四步走）"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【表态】：定性。这是好现象（点赞）、坏现象（批评）、还是复杂的现象（辩证看待）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【分析】：为什么会出现这种现象？它带来了什么深远的影响？"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【对策】：如果是好现象，怎么发扬光大？如果是坏现象，怎么根治？（绝招：从政府、社会、个人三个维度提对策）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【升华】：结合国家大政方针（如乡村振兴、高质量发展）进行拔高收尾。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "愤青式答题：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "面对负面现象，千万不要通篇发泄情绪、痛骂政府不作为。面试是在选拔体制内的人，你必须站在【建设者】的角度，重点放在“如何解决”上！"}]}]}]}$$ AS jsonb), NULL, '社会现象类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "综合分析", "社会现象"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ana_phenomenon", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
